import React, {useEffect, useRef} from "react";
import one from "../assets/story1.jpeg";
import two from "../assets/story2.jpeg";

function Story() {
  const leftColumnRef = useRef(null);
  const imageOneRef = useRef(null);
  const imageTwoRef = useRef(null);

  useEffect(() => {
    const leftColumn = leftColumnRef.current;
    const images = [imageOneRef.current, imageTwoRef.current];
    if (!leftColumn || images.some(image => !image)) return;

    const observerOptions = {
      threshold: 0.1,
    };

    const observerCallback = entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          leftColumn.style.transition = "transform 1s ease-out";
          leftColumn.style.transform = "translateX(0)";

          images.forEach(image => {
            image.style.transition = "transform 1s ease-out";
            image.style.transform = "translateX(0)";
          });
        } else {
          leftColumn.style.transform = "translateX(-100%)";
          images.forEach(image => {
            image.style.transform = "translateX(100%)";
          });
        }
      });
    };

    const observer = new IntersectionObserver(observerCallback, observerOptions);
    observer.observe(leftColumn);
    images.forEach(image => observer.observe(image));

    return () => {
      observer.disconnect();
    };
  }, []);

  return (
    <div className="bg-zinc-900 h-full flex justify-center items-center pt-20 pb-20">
      <div className="max-w-6xl mx-auto p-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div
            className="text-center md:text-left "
            ref={leftColumnRef}
            style={{ transform: "translateX(-100%)" }}
          >
            
            <h1
              className="text-white text-4xl md:text-6xl"
              style={{ fontFamily: "Aldhabi, cursive" }}
            >
              Our Story
            </h1>
            <p
              className="text-white "
              style={{
                fontFamily: "Bookman Old Style, serif",
                fontWeight: 100,
              }}
            >
        

Founded in 2000 in the heart of Lebanon, our company has been dedicated to crafting premium-quality spices that embody the rich flavors and culinary heritage of the region. With a passion for excellence and a commitment to authenticity, we have grown to become a trusted name in the world of spices, offering a diverse range of products that elevate kitchens and dining experiences worldwide.  
Our journey began with a simple mission: to bring the essence of nature's finest ingredients to every table. Over the years, we have perfected the art of sourcing, blending, and preserving the natural aromas and flavors of spices. From vibrant herbs to exotic spice blends, each product reflects our unwavering dedication to quality, freshness, and taste.  
With a focus on sustainability and responsible sourcing, we partner with local farmers and global suppliers to ensure every spice meets the highest industry standards. Our modern production facilities and rigorous quality control processes guarantee that each product maintains its purity and freshness from farm to table.  
Beyond our presence in Lebanon, we proudly export our products to international markets, sharing the rich flavors of Lebanese culinary tradition with the world.
            </p>
          </div>

          <div className="flex justify-center items-center gap-4">
            <div
              className="relative w-64 h-96"
              ref={imageOneRef}
              style={{ transform: "translateX(100%)" }}
            >
              <img src={one} alt="Product Image" className="w-full h-full" />
              <div className="absolute inset-0 bg-black opacity-50"></div>
            </div>
            <div
              className="relative w-64 h-96"
              ref={imageTwoRef}
              style={{ transform: "translateX(100%)" }}
            >
              <img src={two} alt="Product Image" className="w-full h-full" />
              <div className="absolute inset-0 bg-black opacity-50"></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Story;
